  THOUGHT: I found the bug! The `host_label` method in `lib/ansible/plugins/callback/__init__.py` has incorrect logic. When there's no delegation (no `delegated_vars`), it incorrectly returns `"%s -> local" % (hostname,)` instead of just returning the hostname. This is exactly the issue described in the PR.

Let me first create a simple test script to reproduce the issue, then fix it.

```bash
cat <<'EOF' > test_host_label.py
#!/usr/bin/env python3

# Mock objects to simulate the issue
class MockHost:
    def get_name(self):
        return "host1"

class MockResult:
    def __init__(self, has_delegation=False):
        self._host = MockHost()
        if has_delegation:
            self._result = {'_ansible_delegated_vars': {'ansible_host': 'host2'}}
        else:
            self._result = {}

# Current buggy implementation
def buggy_host_label(result):
    hostname = result._host.get_name()
    delegated_vars = result._result.get('_ansible_delegated_vars', None)
    if delegated_vars:
        return "%s -> %s" % (hostname, delegated_vars['ansible_host'])
    return "%s -> local" % (hostname,)

# Fixed implementation
def fixed_host_label(result):
    hostname = result._host.get_name()
    delegated_vars = result._result.get('_ansible_delegated_vars', None)
    if delegated_vars:
        return "%s -> %s" % (hostname, delegated_vars['ansible_host'])
    return hostname

# Test cases
print("Testing buggy implementation:")
print("No delegation:", buggy_host_label(MockResult(has_delegation=False)))
print("With delegation:", buggy_host_label(MockResult(has_delegation=True)))

print("\nTesting fixed implementation:")
print("No delegation:", fixed_host_label(MockResult(has_delegation=False)))
print("With delegation:", fixed_host_label(MockResult(has_delegation=True)))
EOF
```

